#include "unity.h"
#include "header.h"
#include "helpers.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void setUp(void) { }
void tearDown(void) { }

// Helper functions for stdout capture
static char captured_output[1024];
static FILE* original_stdout;

static void capture_stdout_start(void) {
    original_stdout = stdout;
    memset(captured_output, 0, sizeof(captured_output));
    stdout = fmemopen(captured_output, sizeof(captured_output) - 1, "w");
    setbuf(stdout, NULL);
}

static char* capture_stdout_stop(void) {
    fclose(stdout);
    stdout = original_stdout;
    return strdup(captured_output);
}

void unit_test_postorder_display_non_empty_tree(void) {
    node* root = NULL;
    int values[] = {10, 5, 15, 3, 7, 12, 18};
    int size = sizeof(values) / sizeof(values[0]);

    for (int i = 0; i < size; i++) {
        insert_bt(&root, values[i]);
    }

    capture_stdout_start();
    postorder_display(root);
    char* output = capture_stdout_stop();
    TEST_ASSERT_NOT_NULL(output);
    TEST_ASSERT_TRUE(strlen(output) > 0);

    free(output);
    helper_free_tree(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_postorder_display_non_empty_tree);
    return UNITY_END();
}

